import{_ as r,o as e,c as a,a5 as o}from"./chunks/framework.QWVCgkrI.js";const n="/study/images/hardware/ram-cache-and-storage.svg",p=JSON.parse('{"title":"RAM・キャッシュ・ストレージの違い","description":"","frontmatter":{"title":"RAM・キャッシュ・ストレージの違い","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"hardware","summary":"ゲームを読み込み、計算し、セーブする場面から、RAM、CPUキャッシュ、レジスタ、SSDの役割を説明する。容量、遅延、帯域、仮想メモリとの関係も整理する。","aliases":["RAM","DRAM","主記憶","メインメモリ","CPUキャッシュ","L1","L2","L3","レジスタ","SSD","ストレージ","メモリ階層","VRAM"],"verification":"OpenStax・Armのメモリ階層、Intelの計測資料、Microsoftのメモリ管理・ファイルキャッシュ・D3D12資料と照合（2026-11-07）"}},"headers":[],"relativePath":"hardware/memory/ram-cache-and-storage.md","filePath":"hardware/memory/ram-cache-and-storage.md"}'),s={name:"hardware/memory/ram-cache-and-storage.md"};function d(h,t,i,l,c,m){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="ram・キャッシュ・ストレージの違い" tabindex="-1">RAM・キャッシュ・ストレージの違い <a class="header-anchor" href="#ram・キャッシュ・ストレージの違い" aria-label="Permalink to &quot;RAM・キャッシュ・ストレージの違い&quot;">​</a></h1><p>ゲームをインストールすると、プログラムや画像はSSDなどの<strong>ストレージ</strong>に保存されます。ゲームを起動して遊ぶ間は、実行に必要な命令やデータを<strong>RAM</strong>に置き、CPUが処理します。CPUの近くには<strong>キャッシュ</strong>と<strong>レジスタ</strong>もあり、計算で使う値を保持します。まず「どこに保存しておくか」と「いま計算で何を使うか」から、それぞれの役割を見ます。<a href="https://openstax.org/books/introduction-computer-science/pages/5-5-memory-hierarchy" target="_blank" rel="noreferrer">OpenStaxのメモリ階層</a> · <a href="/study/hardware/computer-components.html">コンピュータの構成要素</a></p><h2 id="データを置く場所と目的" tabindex="-1">データを置く場所と目的 <a class="header-anchor" href="#データを置く場所と目的" aria-label="Permalink to &quot;データを置く場所と目的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>場所</th><th>主な役割</th><th>ゲームでの例</th></tr></thead><tbody><tr><td><strong>レジスタ</strong></td><td>CPUの命令が計算の入力や結果を保持する、ごく小さな記憶場所。</td><td>座標の加算で使う現在の値や計算結果。</td></tr><tr><td><strong>CPUキャッシュ</strong></td><td>メモリの一部の内容をCPUの近くで保持し、必要なデータを短い待ち時間で使えるようにする。</td><td>毎フレーム読む敵の座標の一部分。</td></tr><tr><td><strong>RAM・主記憶</strong></td><td>動作中のプログラムやデータを保持する。一般的なPCの主記憶にはDRAMを使う。</td><td>読み込んだマップ、敵の一覧、作業中のセーブ内容。</td></tr><tr><td><strong>SSDなどのストレージ</strong></td><td>ファイルを保存し、通常は電源を切っても内容を保持する。</td><td>インストール済みの画像ファイルやセーブファイル。</td></tr></tbody></table><p>レジスタ・一般的なCPUキャッシュ・DRAMは、電力の供給がなくなると内容を保持できない<strong>揮発性</strong>の記憶です。セーブするには、アプリが保存する内容をファイルとしてストレージへ書き出します。RAMの中でプレイヤーの位置が変わるだけでは、前回のセーブファイルの内容は更新されません。<a href="https://openstax.org/books/introduction-computer-science/pages/5-5-memory-hierarchy" target="_blank" rel="noreferrer">OpenStaxの揮発性と永続ストレージ</a> · <a href="https://support.arm.com/documentation/den0042/latest/Caches" target="_blank" rel="noreferrer">Armのキャッシュとメモリ階層</a></p><figure class="study-figure"><img src="'+n+'" alt="レジスタは命令の入力と結果、CPUキャッシュは近くで使うメモリの一部、RAMは動作中の命令とデータ、SSDは保存するファイルを保持する。CPUの近くの記憶ほど一般に小容量で待ち時間が短く、大きな記憶と組み合わせて使う。RAMとSSDの読み書きはOSのI/O処理に関係する。" width="760" height="430" loading="lazy"><figcaption>役割を比べた図です。L1・L2・L3などの構成や容量はCPUによって異なります。<a href="/study/images/hardware/ram-cache-and-storage.svg" target="_blank" rel="noopener noreferrer">記憶場所の図を拡大</a></figcaption></figure><h2 id="なぜ何種類も組み合わせるのか" tabindex="-1">なぜ何種類も組み合わせるのか <a class="header-anchor" href="#なぜ何種類も組み合わせるのか" aria-label="Permalink to &quot;なぜ何種類も組み合わせるのか&quot;">​</a></h2><p>CPUのすぐ近くで短い待ち時間で使える記憶は、用意できる容量に制約があります。一方、RAMやストレージは大量のデータを置けますが、個々のアクセスを待つ時間が長くなります。そこで、よく使う範囲を近くに保持しながら、大きな記憶も使う構成にします。この組み合わせを<strong>メモリ階層</strong>と呼びます。<a href="https://support.arm.com/documentation/107565/0101/Memory-system/Caches-and-memory-hierarchy/Memory-hierarchy" target="_blank" rel="noreferrer">Armのメモリ階層</a></p><p>CPUキャッシュの<strong>ヒット</strong>は、必要な範囲がそのキャッシュにあることです。<strong>ミス</strong>すると、別のキャッシュやRAMなどからデータを得る必要があります。キャッシュは周辺のバイトを含む<strong>キャッシュライン</strong>という単位で扱うため、配列を隣から順に使うと、一度得た範囲を活用しやすくなります。L1・L2・L3の数字は階層を表し、一般に小さい数字ほどCPUコアに近い側です。<a href="https://learn.arm.com/learning-paths/servers-and-cloud-computing/performix-memory-access/how-to-0/" target="_blank" rel="noreferrer">ArmのCPUメモリ階層</a> · <a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性とAoS・SoA</a></p><h2 id="容量・遅延・帯域を分けて見る" tabindex="-1">容量・遅延・帯域を分けて見る <a class="header-anchor" href="#容量・遅延・帯域を分けて見る" aria-label="Permalink to &quot;容量・遅延・帯域を分けて見る&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指標</th><th>調べること</th><th>例</th></tr></thead><tbody><tr><td><strong>容量</strong></td><td>同時にどれだけ置けるか。</td><td>RAMにマップと敵の状態を合わせて何GB置けるか。</td></tr><tr><td><strong>遅延・レイテンシー</strong></td><td>一つの要求から結果が得られるまで、どれだけ待つか。</td><td>次の敵の参照先を一件ずつ読み、毎回結果を待つ時間。</td></tr><tr><td><strong>帯域</strong></td><td>単位時間にどれだけ転送できるか。</td><td>大きな画像データを連続して読み出すときのGB/s。</td></tr></tbody></table><p>容量を増やすことと、一件の読み取りの待ち時間を短くすることは別の指標です。また、連続転送で高い帯域が出ても、次のアドレスが直前の結果で決まる読み方では、その待ち時間が処理全体に効きます。ゲームでは「読み込む総量」「繰り返し参照する範囲」「一件ずつ待つ箇所」を分けて調べます。<a href="https://www.intel.com/content/www/us/en/developer/articles/tool/intelr-memory-latency-checker.html" target="_blank" rel="noreferrer">Intelの帯域と遅延の測定</a> · <a href="/study/hardware/memory/dram-channels-and-bandwidth.html">DRAMのチャネルと帯域</a></p><h2 id="ファイルのバイトが、アプリのデータになるまで" tabindex="-1">ファイルのバイトが、アプリのデータになるまで <a class="header-anchor" href="#ファイルのバイトが、アプリのデータになるまで" aria-label="Permalink to &quot;ファイルのバイトが、アプリのデータになるまで&quot;">​</a></h2><ol><li>ゲームが必要なファイルと範囲を指定して読み取りを要求します。Windowsの通常のキャッシュ付きI/Oでは、OSはRAM上のファイルキャッシュを使えます。そこにデータがなければストレージからの読み取りが必要になります。</li><li>読み取ったバイトを、ゲームが画像やマップなどのデータとして解釈します。圧縮されたファイルなら展開も行います。アプリが扱うアドレスは通常<strong>仮想アドレス</strong>で、OSとCPUの仕組みにより、実際のRAM上の場所に対応付けられます。</li><li>CPUが命令を実行し、データを読み書きします。CPUキャッシュは、このメモリアクセスを速くするために使われます。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-caching" target="_blank" rel="noreferrer">Microsoftのファイルキャッシュ</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/memory/virtual-address-space" target="_blank" rel="noreferrer">仮想アドレス空間</a></li></ol><p>巨大なファイルは必要な範囲ずつ読み込めます。メモリマップドファイルでは、ファイルの範囲を仮想アドレス空間へ対応付け、アクセスに応じてページ単位で内容を用意できます。どの範囲をいつ読み込むかは、OSとアプリの使う方法によって変わります。<a href="/study/os/memory-mapped-files.html">メモリマップドファイル</a> · <a href="/study/os/file-read-journey.html">ファイルを読むと内部で何が起きるか</a></p><p>セーブではアプリがファイルへの書き込みを要求します。Windowsのキャッシュ付き書き込みでは、RAM上で変更を受け付けてからストレージへ書き出す場合があります。保存の完了をどこまで保証するかは、使うAPIやフラッシュ操作、デバイスの動作も含めて考えます。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-caching" target="_blank" rel="noreferrer">Microsoftのファイルキャッシュ</a> · <a href="/study/os/windows-file-cache.html">Windowsのファイルキャッシュ</a></p><h2 id="gpuが使うメモリ" tabindex="-1">GPUが使うメモリ <a class="header-anchor" href="#gpuが使うメモリ" aria-label="Permalink to &quot;GPUが使うメモリ&quot;">​</a></h2><p><strong>VRAM</strong>は、画像や頂点などGPUが使うデータを保持するメモリを指します。独立したGPUボードでは専用のビデオメモリを持つ構成が一般的です。CPUとGPUが主記憶を共有する構成は<strong>UMA</strong>（Unified Memory Architecture）と呼びます。使える配置と転送方法は構成により変わるので、CPU用のRAM容量とGPU用の表示を合わせて確認します。<a href="https://microsoft.github.io/DirectX-Specs/d3d/ResourceHeaps.html" target="_blank" rel="noreferrer">MicrosoftのD3D12メモリ構成</a> · <a href="/study/hardware/gpu/cpu-vs-gpu.html">CPUとGPUの役割分担</a></p><p>命令がレジスタをどう使うかは<a href="/study/hardware/cpu/instruction-execution.html">CPUの命令実行</a>、仮想アドレスとページは<a href="/study/os/virtual-memory.html">仮想メモリ</a>で説明します。</p>',19)])])}const f=r(s,[["render",d]]);export{p as __pageData,f as default};
